(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const collage=document.querySelector('.collage');if(collage&&!reduce){const shots=[...collage.querySelectorAll('.shot')];collage.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=collage.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;shots.forEach((el,i)=>{const depth=(i%4+1)/4;el.style.transform='translate3d('+(-x*18*depth)+'px,'+(-y*14*depth)+'px,'+(depth*12)+'px) rotateY('+(-x*5*depth)+'deg)'})});collage.addEventListener('pointerleave',()=>shots.forEach(el=>el.style.transform=''))}if(window.gsap&&!reduce){gsap.registerPlugin(ScrollTrigger);gsap.to('.signature h2',{rotationY:24,rotationX:-9,scale:1.08,scrollTrigger:{trigger:'.signature',start:'top bottom',end:'bottom top',scrub:true}})}document.querySelectorAll('.faq details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.faq details').forEach(other=>{if(other!==d)other.open=false})}));})();
(()=>{const button=document.querySelector('.menu'),nav=document.querySelector('.hdr nav');if(!button||!nav)return;button.setAttribute('aria-expanded','false');button.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open)});nav.addEventListener('click',event=>{if(event.target.closest('a')){nav.classList.remove('open');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open menu')}});document.querySelector('.faq').id='faq'})();

(()=>{const preference=matchMedia('(prefers-reduced-motion: reduce)');const touchLayout=matchMedia('(max-width: 799px), (pointer: coarse)');if(preference.matches||touchLayout.matches||!window.Lenis||!window.gsap||!window.ScrollTrigger)return;const scroller=new Lenis({duration:1.15,smoothWheel:true,touchMultiplier:1});scroller.on('scroll',ScrollTrigger.update);gsap.ticker.add(time=>scroller.raf(time*1000));gsap.ticker.lagSmoothing(0);document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();history.pushState(null,'',link.getAttribute('href'));scroller.scrollTo(target,{offset:-70})}));preference.addEventListener('change',event=>{if(event.matches)scroller.destroy()});window.addEventListener('pagehide',()=>scroller.destroy(),{once:true});document.fonts.ready.then(()=>ScrollTrigger.refresh())})();

(()=>{if(!window.gsap||matchMedia('(prefers-reduced-motion: reduce)').matches)return;gsap.registerPlugin(ScrollTrigger);const intro=gsap.timeline({defaults:{ease:'power3.out'}});intro.from('.word-top',{y:-55,opacity:0,duration:.95},0).from('.word-bottom',{y:55,opacity:0,duration:.95},.08).from('.collage .shot',{y:48,rotationX:8,opacity:0,duration:.9,stagger:.055},.17).from('.hero-list,.hero-status,.hero-dock',{y:18,opacity:0,duration:.5,stagger:.08},.6);const heroScroll=gsap.timeline({scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true,invalidateOnRefresh:true,onEnter:()=>{if(intro.isActive())intro.progress(1)}}});heroScroll.fromTo('.word-top',{y:0,opacity:1},{y:()=>innerWidth<800?-70:-100,opacity:.3,immediateRender:false},0).fromTo('.word-bottom',{y:0,opacity:1},{y:()=>innerWidth<800?44:95,opacity:.3,immediateRender:false},0).fromTo('.collage',{y:0,scale:1,opacity:1},{y:-65,scale:.94,opacity:.45,immediateRender:false},0).fromTo('.hero-list,.scroll',{y:0,opacity:1},{y:()=>innerWidth<800?20:0,opacity:()=>innerWidth<800?.15:1,immediateRender:false},0)})();
